export function tacticalMapFor(e){
 const detail=tacticalMaps[e.eid]
 if(!detail)return undefined
 return {caption:detail.caption,points:detail.points.map(([name,lng,lat,kind])=>({name,coordinates:[lng,lat],kind})),references:mapReferences[detail.ref]}
}
